import { defineConfig } from "oxfmt";
import ultracite from "ultracite/oxfmt";

export default defineConfig({
  ...ultracite,
  // Ultracite 8 sorts Tailwind classes. Point the sorter at the docs theme so
  // custom tokens like `bg-code` sort with the built-in utilities.
  sortTailwindcss: {
    ...ultracite.sortTailwindcss,
    stylesheet: "./apps/docs/app/globals.css",
  },
  // The docs search index is generated by the icon build; skip formatting it
  // (the other generated icon dirs are already covered by .gitignore).
  ignorePatterns: [
    ...(ultracite.ignorePatterns ?? []),
    "apps/docs/src/icons-search-index.json",
    // The MIT text is hard-wrapped at 80 columns by convention. Reflowing it
    // into single long lines is what the formatter wants and it should not win.
    "LICENSE.md",
  ],
});
